import{_ as e,o as a,c as r,a7 as d}from"./chunks/framework.BCbKzsgW.js";const c=JSON.parse('{"title":"后台任务处理与调度","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/task-scheduling/index.md","filePath":"development/common/task-scheduling/index.md","lastUpdated":1793441194000}'),n={name:"development/common/task-scheduling/index.md"};function o(i,t,h,s,l,u){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="hou-tai-ren-wu-chu-li-yu-diao-du" tabindex="-1">后台任务处理与调度 <a class="header-anchor" href="#hou-tai-ren-wu-chu-li-yu-diao-du" aria-label="Permalink to &quot;后台任务处理与调度&quot;">​</a></h1><p><strong>后台任务</strong> 是由系统在后台完成的工作，例如定期生成报表、到期检查未付款订单，或在用户上传视频后进行转码。用户可以先收到提交结果，之后再查看处理进度；有些任务由系统自动产生，不需要用户发起请求。</p><p>后台任务处理与调度，就是管理这些工作的 <strong>产生、等待、执行和结果</strong>。它既要决定什么时候处理，也要在失败或服务重启后，知道哪些工作需要继续。</p><h2 id="diao-du-yu-chu-li-fen-bie-zuo-shi-me" tabindex="-1">调度与处理分别做什么 <a class="header-anchor" href="#diao-du-yu-chu-li-fen-bie-zuo-shi-me" aria-label="Permalink to &quot;调度与处理分别做什么&quot;">​</a></h2><ul><li><strong>调度</strong>：决定任务什么时候可以开始。例如每天凌晨执行，或等到订单创建 30 分钟后再检查。</li><li><strong>处理</strong>：执行具体业务动作。例如计算报表、判断订单是否仍未付款、调用视频转码服务。</li></ul><p>任务通常还会 <strong>保存状态</strong>，用来查询进度、安排重试和恢复中断的工作。调度器、执行器和任务存储可以属于同一个应用，规模扩大后也可以拆开部署。</p><h2 id="tong-chang-zen-yang-chu-fa" tabindex="-1">通常怎样触发 <a class="header-anchor" href="#tong-chang-zen-yang-chu-fa" aria-label="Permalink to &quot;通常怎样触发&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>含义</th><th>简单例子</th></tr></thead><tbody><tr><td><a href="./triggers/periodic-tasks.html">周期任务</a></td><td>按固定周期重复执行</td><td>每天凌晨生成销售日报</td></tr><tr><td><a href="./triggers/delayed-tasks.html">延迟任务</a></td><td>等待一段时间或指定时刻后执行</td><td>下单 30 分钟后检查是否需要关闭</td></tr><tr><td><a href="./triggers/event-driven.html">事件驱动任务</a></td><td>业务发生变化后触发</td><td>视频上传完成后开始转码</td></tr></tbody></table><p><strong>异步</strong> 描述的是 <strong>执行方式</strong>：请求不必一直等待后台工作完成。它可以与上面几种触发方式配合，并不只指某一种任务。</p><h2 id="yi-ci-ren-wu-da-zhi-zen-yang-wan-cheng" tabindex="-1">一次任务大致怎样完成 <a class="header-anchor" href="#yi-ci-ren-wu-da-zhi-zen-yang-wan-cheng" aria-label="Permalink to &quot;一次任务大致怎样完成&quot;">​</a></h2><p>系统先保存要做的工作，等待执行条件满足，再由工作进程（Worker）领取、<strong>检查当前业务状态</strong>、执行并记录结果。失败后，根据原因决定重试或转人工处置。</p><p>例如，订单检查任务到期，只表示该检查可以开始；如果用户已经付款，就应跳过关闭。任务入队也只表示进入等待处理的环节，<strong>不能当成业务已经完成</strong>。</p><p>这些任务可以用 <strong>任务定义、调度计划、执行实例、执行尝试</strong> 的模型描述，其中调度计划用于按时间规则生成实例。关系图、状态图和协作时序见<a href="./execution/task-model.html">任务模型与执行流程</a>。简单系统可以从任务表和后台进程开始，再按时效、任务量和恢复要求选择队列或调度平台。</p><h2 id="zhuan-ti-nei-rong" tabindex="-1">专题内容 <a class="header-anchor" href="#zhuan-ti-nei-rong" aria-label="Permalink to &quot;专题内容&quot;">​</a></h2><table tabindex="0"><thead><tr><th>内容</th><th>说明</th></tr></thead><tbody><tr><td><a href="./execution/task-model.html">任务模型与执行流程</a></td><td>通用模型、图示、状态与组件分工</td></tr><tr><td><a href="./triggers/periodic-tasks.html">周期任务与定时轮询</a></td><td>定期执行、到期扫描与错过执行后的补跑</td></tr><tr><td><a href="./triggers/delayed-tasks.html">延迟任务与到期处理</a></td><td>等待到期、改期与旧任务处理</td></tr><tr><td><a href="./triggers/event-driven.html">事件驱动与异步任务</a></td><td>业务变化如何可靠接续后台工作</td></tr><tr><td><a href="./execution/reliability.html">幂等、重试与故障恢复</a></td><td>重复执行、超时与部分成功</td></tr><tr><td><a href="./implementation/database-queue.html">数据库任务队列</a></td><td>任务领取、完成确认与超时回收</td></tr><tr><td><a href="./implementation/observability.html">监控、积压与故障排查</a></td><td>判断任务是否及时完成，定位积压与失败</td></tr><tr><td><a href="./scenarios/batch-design.html">实际业务分析</a></td><td>订单、会员、预约等十类场景，从需求到实现</td></tr></tbody></table><p>业务案例中进一步讨论批量对象、并发处理、通知与恢复，并结合国内厂商公开实践分析取舍。</p>',16)])])}const m=e(n,[["render",o]]);export{c as __pageData,m as default};
